package dev.jobflow.api;
import dev.jobflow.api.JobDtos.*; import dev.jobflow.domain.*; import dev.jobflow.security.AuthenticatedUser; import dev.jobflow.service.JobService; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/jobs") public class JobController {private final JobService jobs;public JobController(JobService j){jobs=j;} @PostMapping public ResponseEntity<JobResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody CreateJobRequest r){Job j=jobs.create(u.id(),r,key);return ResponseEntity.status(HttpStatus.CREATED).body(JobResponse.of(j));} @GetMapping public Page<JobResponse> list(@AuthenticationPrincipal AuthenticatedUser u,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return jobs.listForOwner(u.id(),p).map(JobResponse::of);}@GetMapping("/{id}") public JobResponse get(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID id){return JobResponse.of(jobs.getForOwner(id,u.id()));}@GetMapping("/{id}/result") public JobResponse result(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID id){return JobResponse.of(jobs.getForOwner(id,u.id()));}@PostMapping("/{id}/cancel") public JobResponse cancel(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID id){return JobResponse.of(jobs.cancel(id,u.id()));}}
